"""Account helpers. Balances are integer cents."""


class InsufficientFunds(ValueError):
    """Raised when a withdrawal or transfer exceeds the source balance."""


class Bank:
    def __init__(self):
        self._accounts = {}

    def open_account(self, name, initial=0):
        if name in self._accounts:
            raise ValueError("account exists: " + str(name))
        if initial < 0:
            raise ValueError("initial must be >= 0")
        self._accounts[name] = initial

    def deposit(self, name, amount):
        if amount <= 0:
            raise ValueError("amount must be > 0")
        self._accounts[name] += amount  # KeyError if unknown

    def withdraw(self, name, amount):
        if amount <= 0:
            raise ValueError("amount must be > 0")
        current = self._accounts[name]  # KeyError if unknown
        if current < amount:
            raise InsufficientFunds(...)
        self._accounts[name] = current - amount

    def transfer(self, src, dst, amount):
        if amount <= 0:
            raise ValueError
        if src == dst:
            raise ValueError("cannot transfer to the same account")
        src_bal = self._accounts[src]
        dst_bal = self._accounts[dst]  # ensure dst exists before changing anything
        if src_bal < amount:
            raise InsufficientFunds
        self._accounts[src] = src_bal - amount
        self._accounts[dst] = dst_bal + amount

    def balance(self, name):
        return self._accounts[name]
```

